arguments.command:
set -e; rm -rf /tmp/j92; mkdir /tmp/j92; cd /home/jmercier/Codes/me/agentic-development; cp -r skills tests integration plugin.json /tmp/j92/ 2>/dev/null; cd /tmp/j92
run(){ python3 -B -m unittest tests.test_cycle_disclosure tests.test_trigger_routing 2>&1 | tail -1; }
echo base: $(run)
cp skills/cycle/evals/evals.json /tmp/e.bak
sed -i 's/If cycle is loaded for a single-phase request, it coordinates only Research and stops at the proposed handoff without finalizing./Cycle applies to single-phase development and routes the bounded investigation to Research./' skills/cycle/evals/evals.json; echo evalrevert: $(run); cp /tmp/e.bak skills/cycle/evals/evals.json
cp integration/trigger-routing.json /tmp/m.bak
python3 - <<'E'
import json;p='integration/trigger-routing.json';d=json.load(open(p))
for c in d['cases']:
  if c['query'].startswith('Le paiement'): c['expected_skills']=['research']
json.dump(d,open(p,'w'),ensure_ascii=False)
E
echo case2drop: $(run); cp /tmp/m.bak integration/trigger-routing.json
python3 - <<'E'
import json;p='integration/trigger-routing.json';d=json.load(open(p))
for c in d['cases']:
  if c['query'].startswith('Implement task BILL-14'): c['expected_skills']=['implement','test']
json.dump(d,open(p,'w'),ensure_ascii=False)
E
echo twophase: $(run); cp /tmp/m.bak integration/trigger-routing.json; echo restored: $(run)

